from fractions import Fraction

def is_rational_square(r: Fraction) -> bool:
    """Checks if a rational number r is the square of a rational number."""
    if r < 0:
        return False
    if r == 0:
        return True

    # Reduce the fraction
    r = r.limit_denominator() # Should already be reduced by Fraction, but safe practice

    numerator = r.numerator
    denominator = r.denominator

    # Check if numerator and denominator are perfect squares
    def is_perfect_square(n):
        if n < 0: return False
        if n == 0: return True
        root = int(n**0.5)
        return root * root == n

    return is_perfect_square(numerator) and is_perfect_square(denominator)

def calculate_b_squared(D):
    """Calculates b^2 = D^2 + 4D + 3 - 2/D."""
    if D == 0:
        return None # Undefined

    # Use fractions for exact arithmetic
    try:
        return Fraction(D**2 + 4*D + 3) - Fraction(2, D)
    except ZeroDivisionError:
        return None

